(* 블록 명령(LMMV·HMMV·LMMM·HMMM·YMMM·LMMC·HMMC)과 LINE 이 끝난 뒤 레지스터.

   명령은 줄을 마칠 때마다 DY 와 NY(복사 명령은 SY 도)를 바꾸고, 다음 명령이 이
   값을 다시 쓰지 않으면 그 값에서 시작한다(openMSX VDPCmdEngine 의
   `DY += TY; --NY`). SX·DX·NX 는 바뀌지 않는다. LINE 은 짧은 변으로 갈 때마다
   DY 가 바뀐다. 레지스터는 읽을 수 없어서 명령 두 개를 이어 돌려 두 번째 명령의
   결과로 본다: 두 번째 명령은 바뀐 레지스터만 쓴다.

   기대값은 같은 명령열을 MSX2 카트리지 ROM 으로 만들어(필요한 레지스터만
   R#32..R#46 에 쓰고 CE 가 내려갈 때까지 S#2 를 읽는다. LMMC·HMMC 는 R#17 = 0xAC
   로 R#44 를 가리키고 바이트마다 포트 0x9B 에 쓴 뒤 기다린다) openMSX
   (my8250cbios)에서 돌려 물리 VRAM 128KB 를 덤프한 것이다. 시나리오마다 12줄 띠
   (논리 순서 바이트)의 MD5 와 전체 VRAM 의 MD5 를 적었다. 같은 ROM 을 이
   에뮬레이터로 돌린 VRAM 도 모든 모드(SCREEN 5~8)에서 openMSX 덤프와 바이트
   단위로 같았다. *)

let failures = ref 0

let check name cond =
  if not cond then begin
    incr failures;
    Printf.eprintf "FAIL %s\n%!" name
  end

let set_reg t r v =
  Vdp.io_write t ~port:0x99 v;
  Vdp.io_write t ~port:0x99 (0x80 lor r)

type step =
  | Regs of (int * int) list  (* 레지스터 쓰기, 마지막이 R#46 *)
  | Data of int list          (* R#44 로 보내는 CPU 전송 바이트 *)

let run_step t = function
  | Regs writes -> List.iter (fun (r, v) -> set_reg t r v) writes
  | Data bytes ->
    set_reg t 17 0xac;
    List.iter (fun b -> Vdp.io_write t ~port:0x9b b) bytes;
    set_reg t 17 0

let band_digest t ~planar ~stride ~y0 =
  let b = Bytes.create (12 * stride) in
  for k = 0 to (12 * stride) - 1 do
    let a = (y0 * stride) + k in
    let phys = if planar then ((a land 1) lsl 16) lor (a lsr 1) else a in
    Bytes.set b k (Char.chr (Vdp.vram_read t phys))
  done;
  Digest.to_hex (Digest.bytes b)

(* 띠의 MD5 는 시나리오를 전부 돌린 뒤에 잰다: 이어 도는 명령이 위쪽 띠에
   닿을 수 있고 openMSX 덤프가 그 시점의 VRAM 이다. *)
let run_mode (label, r0, planar, stride, scenarios, whole) =
  let t = Vdp.create () in
  List.iter (fun (r, v) -> set_reg t r v)
    [ (1, 0x00); (0, r0); (2, 0x1f); (7, 0); (8, 0x0a); (9, 0x80) ];
  List.iter (fun (r, v) -> set_reg t r v)
    [ (32, 0); (33, 0); (34, 0); (35, 0); (36, 0); (37, 0); (38, 0); (39, 0);
      (40, 0); (41, 0); (42, 0); (43, 0); (44, 0); (45, 0); (46, 0x80) ];
  List.iter (fun (_, _, steps, _) -> List.iter (run_step t) steps) scenarios;
  List.iter
    (fun (name, y0, _, digest) ->
      let got = band_digest t ~planar ~stride ~y0 in
      check (Printf.sprintf "%s %s: band MD5 %s, openMSX %s" label name got digest) (got = digest))
    scenarios;
  let all = Bytes.create 0x20000 in
  for a = 0 to 0x1ffff do Bytes.set all a (Char.chr (Vdp.vram_read t a)) done;
  let got = Digest.to_hex (Digest.bytes all) in
  check (Printf.sprintf "%s whole VRAM MD5 %s, openMSX %s" label got whole) (got = whole)

